package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId string
	OrStat string
	OrQty int64
	OrPrice decimal.Decimal
}

var WsEofFlag string
var WsTotal decimal.Decimal
var WsGrand decimal.Decimal
var WsNewCount int64
var WsShipCount int64
var WsCancelCount int64
var WsInvalid int64
var WsBadQty int64
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var OrderFile *os.File
var orderReader *bufio.Reader
var OrderRecData OrderRec

func formatZZ9(v int64, width int) string {
	s := fmt.Sprintf("%0*d", width, v)
	// drop high-order if overflow - but for this program width matches
	if len(s) > width {
		s = s[len(s)-width:]
	}
	b := []byte(s)
	// Z suppression: replace leading zeros with spaces, but keep last digit
	for i := 0; i < width-1; i++ {
		if b[i] == '0' {
			b[i] = ' '
		} else {
			break
		}
	}
	return string(b)
}

func formatNumericEdited(d decimal.Decimal, pic string) string {
	// Determine scale from pic (digits after '.')
	dotIdx := strings.Index(pic, ".")
	scale := 0
	if dotIdx >= 0 {
		scale = len(pic) - dotIdx - 1
	}
	// Truncate toward zero to scale (COBOL default store without rounded)
	// For display we need the value as stored. WsTotal etc are already truncated/rounded.
	// Format using truncated string representation
	d = d.Truncate(int32(scale))

	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}

	// Get integer and fractional parts
	// Use string with fixed scale
	s := d.StringFixed(int32(scale)) // e.g. "1234.50"
	var intPart, fracPart string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPart = parts[0]
		fracPart = parts[1]
	} else {
		intPart = s
	}

	// int picture is pic[0:dotIdx] if dot else whole pic
	intPic := pic
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
	}
	intWidth := len(intPic)

	// If intPart longer than intWidth, drop high-order digits
	if len(intPart) > intWidth {
		intPart = intPart[len(intPart)-intWidth:]
	} else if len(intPart) < intWidth {
		intPart = strings.Repeat("0", intWidth-len(intPart)) + intPart
	}

	// Apply Z suppression and comma handling
	intBytes := []byte(intPart)
	picBytes := []byte(intPic)

	// First pass: Z suppression
	suppressing := true
	for i := 0; i < intWidth; i++ {
		isZ := picBytes[i] == 'Z'
		isNine := picBytes[i] == '9'
		_ = isNine
		if isZ && suppressing {
			if intBytes[i] == '0' {
				intBytes[i] = ' '
			} else {
				suppressing = false
			}
		} else if picBytes[i] == ',' {
			if suppressing {
				// check if any non-space digit remains after suppression zone
				// In COBOL, commas inside suppressed zone become spaces
				intBytes[i] = ' '
			} else {
				// keep comma as is? Actually comma in data is not present; we need to insert commas per picture
				// But our intPart currently has digits only, no commas. Pic commas should be literals where digits exist.
				// So if suppressing ended, comma remains ','
				intBytes[i] = ','
				// But we replaced intPart which had no commas; need to handle correctly:
				// Actually intPic contains commas at fixed positions; the data digits map to 9/Z positions only.
				// Simpler: build output from pic
			}
		} else {
			// 9 or other
			if intBytes[i] != ' ' {
				suppressing = false
			}
		}
	}
	// The above naive approach fails because intPart has no commas but pic does.
	// Rebuild properly: map digit positions
	// Build result of len intWidth
	result := make([]byte, intWidth)
	// Collect digit chars for 9/Z slots
	digitIdx := 0
	// digits string is intPart without commas (already pure digits padded to intWidth digit slots? No)
	// Actually intWidth includes commas, digit count is less.
	// Count digit slots
	digitSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			digitSlots++
		}
	}
	// intPart currently is intWidth chars (with leading zeros) but should be digitSlots chars
	// Re-derive digits padded to digitSlots
	digits := d.Truncate(int32(scale)).Abs().StringFixed(int32(scale))
	if scale > 0 {
		digits = strings.SplitN(digits, ".", 2)[0]
	}
	if len(digits) > digitSlots {
		digits = digits[len(digits)-digitSlots:]
	} else if len(digits) < digitSlots {
		digits = strings.Repeat("0", digitSlots-len(digits)) + digits
	}
	db := []byte(digits)
	di := 0
	suppressing = true
	for i := 0; i < intWidth; i++ {
		pc := intPic[i]
		if pc == 'Z' {
			ch := db[di]
			di++
			if suppressing && ch == '0' {
				// look ahead: if all remaining Z digits are zero and no 9 non-zero? Actually keep last digit
				// Check if any future non-zero digit in digit slots
				remainingNonZero := false
				for k := di; k < len(db); k++ {
					if db[k] != '0' {
						remainingNonZero = true
						break
					}
				}
				// Also 9 slots always print; if no 9 slots after, need to keep last Z as 0 without suppression?
				// COBOL: last digit before decimal always prints even if zero (because suppression stops at last position)
				// For ZZ9, the '9' ensures at least one zero prints. For Z,ZZ9.99 similar.
				// If all remaining digits are zero, we still suppress this leading zero (it becomes space)
				if !remainingNonZero {
					// check if there are any '9' slots remaining that will print 0
					hasNineAfter := false
					for k := i + 1; k < len(intPic); k++ {
						if intPic[k] == '9' {
							hasNineAfter = true
							break
						}
					}
					if hasNineAfter {
						result[i] = ' '
					} else {
						// this is the last digit slot, should print 0
						result[i] = '0'
						suppressing = false
					}
				} else {
					result[i] = ' '
				}
			} else {
				result[i] = ch
				suppressing = false
			}
		} else if pc == '9' {
			ch := db[di]
			di++
			result[i] = ch
			suppressing = false
		} else if pc == ',' {
			if suppressing {
				result[i] = ' '
			} else {
				result[i] = ','
			}
		}
	}
	out := string(result)
	if scale > 0 {
		out += "." + fracPart
	}
	if neg {
		// not needed for this program
	}
	return out
}

func moveQtyEd(v int64) {
	WsQtyEd = formatZZ9(v, 3)
}
func movePriceEd(d decimal.Decimal) {
	WsPriceEd = formatNumericEdited(d, "Z,ZZ9.99")
}
func moveTotalEd(d decimal.Decimal) {
	WsTotalEd = formatNumericEdited(d, "ZZ,ZZZ,ZZ9.99")
}
func moveGrandEd(d decimal.Decimal) {
	WsGrandEd = formatNumericEdited(d, "Z,ZZZ,ZZZ,ZZ9.99")
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseOrderRec(line string) OrderRec {
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	var r OrderRec
	r.OrId = line[0:5]
	r.OrStat = line[5:6]
	qtyStr := strings.TrimSpace(line[6:9])
	if qtyStr == "" {
		r.OrQty = 0
	} else {
		var v int64
		fmt.Sscanf(qtyStr, "%d", &v)
		r.OrQty = v
	}
	priceStr := strings.TrimSpace(line[9:15])
	if priceStr == "" {
		r.OrPrice = decimal.Zero
	} else {
		var v int64
		fmt.Sscanf(priceStr, "%d", &v)
		r.OrPrice = decimal.New(v, -2)
	}
	return r
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func main() {
	WsEofFlag = "N"
	WsTotal = decimal.Zero
	WsGrand = decimal.Zero
	WsNewCount = 0
	WsShipCount = 0
	WsCancelCount = 0
	WsInvalid = 0
	WsBadQty = 0

	var err error
	OrderFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer OrderFile.Close()
	orderReader = bufio.NewReader(OrderFile)

	MAIN_PARA()
}

func MAIN_PARA() {
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	// CLOSE done via defer
	SUMMARY_PARA()
}

func READ_PARA() {
	line, err := orderReader.ReadString('\n')
	if err != nil {
		// EOF
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
		// last line without newline
		line = strings.TrimRight(line, "\r\n")
		OrderRecData = parseOrderRec(line)
		// Next read will hit EOF; but COBOL would have read this record.
		// We need to handle one-record buffering: we already consumed it.
		// To mimic COBOL, we should not set EOF yet. Use a flag for pending EOF.
		// Instead, read will succeed this time; next call will set EOF.
		// So we defer EOF: save that we have consumed last line, next call returns EOF.
		// Implement via a simple state: if err == io.EOF and line != "" we have a valid record now,
		// and next read should return EOF.
		// We achieve by storing a pending EOF.
		pendingEOF = true
		return
	}
	line = strings.TrimRight(line, "\r\n")
	OrderRecData = parseOrderRec(line)
}

var pendingEOF bool

func init() {
	// wrap READ_PARA to handle pending
}

func PROCESS_PARA() {
	WsTotal = decimal.Zero
	if OrderRecData.OrQty == 0 {
		WsBadQty++
		fmt.Printf("%s BAD QTY\n", OrderRecData.OrId)
	} else if OrderRecData.OrStat == "N" {
		WsTotal = OrderRecData.OrPrice.Mul(decimal.NewFromInt(OrderRecData.OrQty))
		WsTotal = WsTotal.Truncate(2)
		WsNewCount++
		SHOW_PARA()
	} else if OrderRecData.OrStat == "S" {
		prod := OrderRecData.OrPrice.Mul(decimal.NewFromInt(OrderRecData.OrQty))
		prod = prod.Mul(decimal.NewFromFloat(1.05))
		WsTotal = prod.Round(2)
		WsShipCount++
		SHOW_PARA()
	} else if OrderRecData.OrStat == "C" {
		WsCancelCount++
		SHOW_PARA()
	} else {
		WsInvalid++
		fmt.Printf("%s BAD STATUS %s\n", OrderRecData.OrId, OrderRecData.OrStat)
	}
	WsGrand = WsGrand.Add(WsTotal)
	// check pending EOF handling for READ
	if pendingEOF {
		WsEofFlag = "Y"
		pendingEOF = false
	} else {
		READ_PARA()
	}
}

func SHOW_PARA() {
	moveQtyEd(OrderRecData.OrQty)
	movePriceEd(OrderRecData.OrPrice)
	moveTotalEd(WsTotal)
	fmt.Printf("%s %s %s %s %s\n", OrderRecData.OrId, OrderRecData.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SUMMARY_PARA() {
	moveGrandEd(WsGrand)
	// DISPLAY "NEW: " WS-NEW-COUNT " SHIPPED: " WS-SHIP-COUNT " CANCELLED: " WS-CANCEL-COUNT
	// WS-NEW-COUNT is PIC 99 -> zero-padded width 2 with DISPLAY? The spec says unedited numeric DISPLAY prints zero-padded.
	// In COBOL DISPLAY of PIC 99 prints two digits zero-padded.
	fmt.Printf("NEW: %02d SHIPPED: %02d CANCELLED: %02d\n", WsNewCount, WsShipCount, WsCancelCount)
	fmt.Printf("INVALID: %02d BAD QTY: %02d\n", WsInvalid, WsBadQty)
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

