		parts := strings.SplitN(s, ".", 2)
		if len(parts) == 2 {
			fracPart = parts[1]
		} else {
			fracPart = strings.Repeat("0", scale)
		}
		if len(fracPart) < scale {
			fracPart = fracPart + strings.Repeat("0", scale-len(fracPart))
		} else if len(fracPart) > scale {
			fracPart = fracPart[:scale]
		}
	}

	digitSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			digitSlots++
		}
	}
	digits := d.Abs().StringFixed(int32(scale))
	if scale > 0 {
		digits = strings.SplitN(digits, ".", 2)[0]
	}
