					for k := i + 1; k < len(intPic); k++ {
						if intPic[k] == '9' {
							hasNineAfter = true
							break
						}
					}
					if hasNineAfter {
						result[i] = ' '
					} else {
						result[i] = '0'
						suppressing = false
					}
				} else {
					result[i] = ' '
				}
			} else {
				result[i] = ch
				suppressing = false
			}
		} else if pc == '9' {
